def _is_verifiable_deterministic_acceptance(
    gate_input: ModelQualityGateInput,
    dod_deterministic: tuple[str, ...],
) -> bool:
    """Return whether this contract path uses deterministic acceptance authority."""
    if gate_input.task_type not in _VERIFIABLE_TASK_TYPES:
        return False
    if not dod_deterministic:
        return False
    # OMN-13375: reject-only checks (like no_refusal) cannot grant adequacy.
    # Require at least one non-reject-only check to promote to passed.
    reject_only_checks = {"no_refusal", "schema", "length", "marker"}
    has_promotion_capable_check = any(
        check not in reject_only_checks for check in dod_deterministic
    )
    return has_promotion_capable_check
